func (h *EntityHandler) Insert(ctx context.Context, req *restful.InsertReq) (*restful.InsertResp, error) {
    // Type coercion via strconv.ParseInt for string to Int64
    for _, entity := range req.Data {
        if pkField, ok := entity["id"]; ok {
            if pkStr, isStr := pkField.(string); isStr {
                if pkVal, err := strconv.ParseInt(pkStr, 10, 64); err == nil {
                    entity["id"] = pkVal  // Auto-convert string to Int64
                }
            }
        }
    }
    // Continue with insert using converted types
    return m.Insert(ctx, collectionName, partitionName, req.Data)
}
